/**
 * Importable JSON template of the engine workflow (workflow-templates/command-center-engine.workflow.json).
 * Generated by scripts/gen-workflow-templates.mjs; a unit test fails when the checked-in file drifts.
 * Placeholder app id `my.command.center` (the action id is `<appId>:run-engine`). The workflow holds no
 * provider configuration or secret: the action reads everything from the app at run time.
 */

import type { WorkflowCreate } from "@dynatrace-sdk/client-automation";
import { defaultSettings } from "../domainPort";
import { buildEngineWorkflowCreate } from "./definition";

export const TEMPLATE_APP_ID = "my.command.center";

export function buildEngineTemplate(): WorkflowCreate {
  const settings = defaultSettings();
  return buildEngineWorkflowCreate({ appId: TEMPLATE_APP_ID, settings });
}

export function engineTemplateJson(): string {
  return `${JSON.stringify(buildEngineTemplate(), null, 2)}\n`;
}
